To write unit tests for the `LoggerExtensions.IOCallback` method, we need to mock the `ILogger` and `Utility` dependencies. We'll use Moq to create mock objects for these dependencies.

Here's a plan:
1. Mock the `ILogger` to verify that `LogError` is called with the correct parameters.
2. Mock the `Utility` class to return a specific error message.
3. Test the `IOCallback` method with different error codes to ensure it behaves correctly.

Let's start by submitting the first test file.

<tool>submit_test(csharp)</tool>
```csharp
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Tsavorite.core;
using Garnet.cluster;

public class LoggerExtensionsTests
{
    [Fact]
    public void IOCallback_LogsError_WhenErrorCodeIsNonZero()
    {
        // Arrange
        var loggerMock = new Mock<ILogger>();
        uint errorCode = 1;
        uint numBytes = 10;
        var context = new SemaphoreSlim(0);

        var errorMessage = "Test error message";
        Utility.GetCallbackErrorMessage = (code, bytes, ctx) => errorMessage;

        // Act
        LoggerExtensions.IOCallback(loggerMock.Object, errorCode, numBytes, context);

        // Assert
        loggerMock.Verify(
            logger => logger.LogError(
                "[ClusterUtils] OverlappedStream GetQueuedCompletionStatus error: {errorCode} msg: {errorMessage}",
                errorCode,
                errorMessage),
            Times.Once);
    }

    [Fact]
    public void IOCallback_DoesNotLogError_WhenErrorCodeIsZero()
    {
        // Arrange
        var loggerMock = new Mock<ILogger>();
        uint errorCode = 0;
        uint numBytes = 10;
        var context = new SemaphoreSlim(0);

        // Act
        LoggerExtensions.IOCallback(loggerMock.Object, errorCode, numBytes, context);

        // Assert
        loggerMock.Verify(
            logger => logger.LogError(
                It.IsAny<string>(),
                It.IsAny<object[]>()),
            Times.Never);
    }
}
```

